function s(n){if(!n)return"-";const e=String(n).replace(/[^0-9]/g,"");if(e.length===0)return"-";if(e.startsWith("02")){const t=e.slice(2);return t.length<=7?`02-${t.slice(0,3)}-${t.slice(3)}`.replace(/-$/,""):`02-${t.slice(0,4)}-${t.slice(4)}`}if(e.length===11)return`${e.slice(0,3)}-${e.slice(3,7)}-${e.slice(7)}`;if(e.length===10)return`${e.slice(0,3)}-${e.slice(3,6)}-${e.slice(6)}`;if(e.length===8)return`${e.slice(0,4)}-${e.slice(4)}`;if(e.length>3&&e.length<=12){const t=e.slice(0,3),r=e.slice(3,e.length-4),i=e.slice(-4);return[t,r,i].filter(Boolean).join("-")}return e}function c(n,e="원"){if(n==null||n==="")return"-";const t=typeof n=="string"?Number(n):n;return Number.isNaN(t)?"-":`${Number(t).toLocaleString("ko-KR")}${e||""}`}export{c as a,s as f};
